const b = ($input.first().json.body) ? $input.first().json.body : $input.first().json;

const customerName  = b.customer_name  || b.full_name || b.name || 'Valued Customer';
const customerEmail = b.customer_email || b.email     || '';
const eventType     = b.event_type     || 'Event';
const roomName      = b.room_name      || b.rooms?.[0]?.name || 'TBC';
const eventDate     = b.event_date     || b.date_from || null;
const startTime     = b.start_time     || null;
const endTime       = b.end_time       || null;
const guestCount    = b.guest_count    || b.num_people || null;
const venueName     = b.venue_name     || 'our venue';
const requestId     = b.booking_request_id || b.request_id || '';

const fmtDate = d => {
  if (!d) return '—';
  const dt = new Date(String(d).slice(0,10) + 'T00:00:00');
  return dt.toLocaleDateString('en-GB', { weekday:'long', day:'numeric', month:'long', year:'numeric' });
};

if (!customerEmail) return [];

const subject = `📬 Enquiry Received — ${venueName} | VenueDesk`;

const html = `<!DOCTYPE html>
<html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"></head>
<body style="margin:0;padding:0;background:#f8fafc;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;">
  <div style="max-width:600px;margin:0 auto;padding:32px 16px;">
    <div style="background:linear-gradient(135deg,#6366f1 0%,#4f46e5 100%);border-radius:12px 12px 0 0;padding:28px 32px;text-align:center;">
      <p style="margin:0 0 4px;color:rgba(255,255,255,.8);font-size:11px;letter-spacing:2px;text-transform:uppercase;">VenueDesk · Booking System</p>
      <h1 style="margin:0 0 6px;color:#fff;font-size:22px;font-weight:700;">📬 Enquiry Received</h1>
      <p style="margin:0;color:rgba(255,255,255,.9);font-size:14px;">We'll review your request shortly</p>
    </div>
    <div style="background:#fff;border:1px solid #e2e8f0;border-top:none;border-radius:0 0 12px 12px;padding:32px;">
      <p style="margin:0 0 16px;color:#111827;font-size:15px;">Hi <strong>${customerName}</strong>,</p>
      <p style="margin:0 0 20px;color:#4b5563;font-size:14px;line-height:1.65;">
        Thank you for your enquiry! We've received your request to hire <strong>${venueName}</strong> 
        and a member of our team will review it and be in touch within <strong>24–48 hours</strong> 
        to confirm availability and next steps.
      </p>

      <!-- Enquiry Summary -->
      <div style="background:#f9fafb;border:1px solid #e5e7eb;border-radius:10px;padding:20px;margin-bottom:24px;">
        <h3 style="margin:0 0 14px;color:#111827;font-size:14px;font-weight:700;text-transform:uppercase;letter-spacing:.04em;">📋 Your Enquiry Summary</h3>
        <table style="width:100%;border-collapse:collapse;font-size:13px;">
          <tr><td style="padding:5px 0;color:#6b7280;width:38%;">Space Requested</td><td style="padding:5px 0;color:#111827;font-weight:600;">${roomName}</td></tr>
          <tr><td style="padding:5px 0;color:#6b7280;">Event Type</td><td style="padding:5px 0;color:#111827;font-weight:600;">${eventType}</td></tr>
          ${eventDate ? `<tr><td style="padding:5px 0;color:#6b7280;">Preferred Date</td><td style="padding:5px 0;color:#111827;font-weight:600;">${fmtDate(eventDate)}</td></tr>` : ''}
          ${(startTime && endTime) ? `<tr><td style="padding:5px 0;color:#6b7280;">Preferred Time</td><td style="padding:5px 0;color:#111827;font-weight:600;">${String(startTime).slice(0,5)} – ${String(endTime).slice(0,5)}</td></tr>` : ''}
          ${guestCount ? `<tr><td style="padding:5px 0;color:#6b7280;">Number of Guests</td><td style="padding:5px 0;color:#111827;font-weight:600;">${guestCount}</td></tr>` : ''}
        </table>
      </div>

      <!-- Important notice -->
      <div style="background:#eff6ff;border:1px solid #bfdbfe;border-left:4px solid #6366f1;border-radius:8px;padding:14px 16px;margin-bottom:24px;">
        <p style="margin:0;color:#1e40af;font-size:13px;font-weight:600;">📌 Important: 7-Day Confirmation Window</p>
        <p style="margin:8px 0 0;color:#1e3a8a;font-size:13px;line-height:1.55;">
          Your enquiry will remain active for <strong>7 days</strong>. To secure your booking, 
          a deposit must be paid within this period. Our team will contact you with payment options 
          after reviewing your request.
        </p>
      </div>

      <p style="margin:0 0 20px;color:#4b5563;font-size:14px;line-height:1.65;">
        If you have any questions in the meantime, don't hesitate to reach out — we're here to help make your event a success!
      </p>

      <div style="text-align:center;margin:24px 0 20px;">
        <a href="mailto:bookings@venuedesk.co.uk?subject=Following%20up%20on%20my%20venue%20enquiry"
           style="display:inline-block;background:#6366f1;color:#fff;text-decoration:none;padding:13px 32px;border-radius:8px;font-size:14px;font-weight:600;">
          Get in Touch →
        </a>
      </div>

      <div style="border-top:1px solid #f3f4f6;padding-top:20px;margin-top:8px;">
        <p style="margin:0 0 3px;font-size:13px;color:#374151;font-weight:600;">VenueDesk Booking Team</p>
        <p style="margin:0 0 3px;font-size:12px;color:#6b7280;">📧 bookings@venuedesk.co.uk</p>
        ${requestId ? `<p style="margin:10px 0 0;font-size:11px;color:#9ca3af;">Enquiry Reference: ${requestId}</p>` : ''}
      </div>
    </div>
  </div>
</body></html>`;

return [{ json: { email: customerEmail, subject, html, customer_name: customerName } }];

const b = $('Webhook: New Enquiry Email').first().json.body || $('Webhook: New Enquiry Email').first().json;

const customerName  = b.customer_name  || b.full_name || b.name || 'Unknown';
const customerEmail = b.customer_email || b.email     || '—';
const customerPhone = b.phone || '—';
const eventType     = b.event_type     || '—';
const roomName      = b.room_name      || b.rooms?.[0]?.name || 'TBC';
const eventDate     = b.event_date     || b.date_from || null;
const startTime     = b.start_time     || null;
const endTime       = b.end_time       || null;
const guestCount    = b.guest_count    || b.num_people || '—';
const staffEmail    = b.staff_notification_email || 'bookings@venuedesk.co.uk';
const requestId     = b.booking_request_id || b.request_id || 'N/A';
const tenantId      = b.tenant_id || '';

const fmtDate = d => {
  if (!d) return '—';
  const dt = new Date(String(d).slice(0,10) + 'T00:00:00');
  return dt.toLocaleDateString('en-GB', { weekday:'long', day:'numeric', month:'long', year:'numeric' });
};

const now = new Date().toLocaleString('en-GB', { timeZone: 'Europe/London', dateStyle: 'short', timeStyle: 'short' });

const subject = `🔔 New Venue Enquiry — ${customerName} | ${fmtDate(eventDate)}`;

const html = `<!DOCTYPE html>
<html><head><meta charset="UTF-8"></head>
<body style="margin:0;padding:0;background:#f8fafc;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;">
  <div style="max-width:560px;margin:0 auto;padding:24px 16px;">
    <div style="background:linear-gradient(135deg,#0f172a 0%,#1e293b 100%);border-radius:10px 10px 0 0;padding:20px 24px;">
      <p style="margin:0 0 3px;color:#94a3b8;font-size:10px;letter-spacing:2px;text-transform:uppercase;">VenueDesk · Staff Alert</p>
      <h1 style="margin:0;color:#fff;font-size:18px;font-weight:700;">🔔 New Enquiry Received</h1>
      <p style="margin:6px 0 0;color:#64748b;font-size:12px;">${now}</p>
    </div>
    <div style="background:#fff;border:1px solid #e2e8f0;border-top:none;border-radius:0 0 10px 10px;padding:24px;">
      <table style="width:100%;border-collapse:collapse;font-size:13px;">
        <tr style="background:#f8fafc;"><th colspan="2" style="padding:8px 10px;text-align:left;color:#6366f1;font-size:11px;text-transform:uppercase;letter-spacing:.05em;">Customer Details</th></tr>
        <tr><td style="padding:6px 10px;color:#6b7280;border-bottom:1px solid #f1f5f9;width:35%;">Name</td><td style="padding:6px 10px;color:#111827;font-weight:600;border-bottom:1px solid #f1f5f9;">${customerName}</td></tr>
        <tr><td style="padding:6px 10px;color:#6b7280;border-bottom:1px solid #f1f5f9;">Email</td><td style="padding:6px 10px;border-bottom:1px solid #f1f5f9;"><a href="mailto:${customerEmail}" style="color:#6366f1;">${customerEmail}</a></td></tr>
        <tr><td style="padding:6px 10px;color:#6b7280;border-bottom:1px solid #f1f5f9;">Phone</td><td style="padding:6px 10px;color:#111827;border-bottom:1px solid #f1f5f9;">${customerPhone}</td></tr>
        <tr style="background:#f8fafc;"><th colspan="2" style="padding:8px 10px;text-align:left;color:#6366f1;font-size:11px;text-transform:uppercase;letter-spacing:.05em;padding-top:14px;">Booking Request</th></tr>
        <tr><td style="padding:6px 10px;color:#6b7280;border-bottom:1px solid #f1f5f9;">Space</td><td style="padding:6px 10px;color:#111827;font-weight:600;border-bottom:1px solid #f1f5f9;">${roomName}</td></tr>
        <tr><td style="padding:6px 10px;color:#6b7280;border-bottom:1px solid #f1f5f9;">Event Type</td><td style="padding:6px 10px;color:#111827;border-bottom:1px solid #f1f5f9;">${eventType}</td></tr>
        <tr><td style="padding:6px 10px;color:#6b7280;border-bottom:1px solid #f1f5f9;">Date</td><td style="padding:6px 10px;color:#111827;font-weight:600;border-bottom:1px solid #f1f5f9;">${fmtDate(eventDate)}</td></tr>
        ${(startTime && endTime) ? `<tr><td style="padding:6px 10px;color:#6b7280;border-bottom:1px solid #f1f5f9;">Time</td><td style="padding:6px 10px;color:#111827;border-bottom:1px solid #f1f5f9;">${String(startTime).slice(0,5)} – ${String(endTime).slice(0,5)}</td></tr>` : ''}
        <tr><td style="padding:6px 10px;color:#6b7280;border-bottom:1px solid #f1f5f9;">Guests</td><td style="padding:6px 10px;color:#111827;border-bottom:1px solid #f1f5f9;">${guestCount}</td></tr>
        <tr><td style="padding:6px 10px;color:#6b7280;">Ref ID</td><td style="padding:6px 10px;color:#111827;font-family:monospace;font-size:11px;">${requestId}</td></tr>
      </table>
      <div style="text-align:center;margin:20px 0 4px;">
        <a href="https://andyjay72.github.io/VenueDesk/index.html"
           style="display:inline-block;background:#6366f1;color:#fff;text-decoration:none;padding:11px 24px;border-radius:7px;font-size:13px;font-weight:600;">
          Review in Dashboard →
        </a>
      </div>
    </div>
  </div>
</body></html>`;

return [{ json: { email: staffEmail, subject, html } }];
